mapper.select:
SELECT COUNT(*) FROM food_options
WHERE user_id = #{userId} AND active_unique_key = #{activeKey} AND deleted_at IS NULL
AND id != #{excludeId}

mapper.update:
UPDATE food_options
SET name = #{food.name},
    normalized_name = #{food.normalizedName},
    category = #{food.category},
    default_price = #{food.defaultPrice},
    active_unique_key = #{food.activeUniqueKey},
    updated_at = #{food.updatedAt}
WHERE id = #{food.id}
  AND user_id = #{userId}
  AND deleted_at IS NULL
